script:
if doc.workflow_state == "Enviado":
        
    if not doc.origen:
        frappe.throw("Para enviar el gerenciamiento es necesario el origen.")
            
    if not doc.destino:
        frappe.throw("Para enviar el gerenciamiento es necesario el destino.")
                    
    if not doc.tiempo_de_la_ruta:
        frappe.throw("Para enviar el gerenciamiento es necesario el tiempo de la ruta.")
        
    if not doc.motivo:
        frappe.throw("Para enviar el gerenciamiento es necesario el motivo.")
                
    if not doc.conductor:
        frappe.throw("Para enviar el gerenciamiento es necesario el conductor.")
                        
    if not doc.vehículo:
        frappe.throw("Para enviar el gerenciamiento es necesario el vehículo.")
        
                                
    if not doc.distancia_por_recorrer:
        frappe.throw("Para enviar el gerenciamiento es necesario el punto de distancia por recorrer.")
                                
    if not doc.condiciones_de_la_via:
        frappe.throw("Para enviar el gerenciamiento es necesario el punto de condiciones de la Via.")
                                
    if not doc.clima:
        frappe.throw("Para enviar el gerenciamiento es necesario el punto de clima.")
                                
    if not doc.comunicaciones_disponibles:
        frappe.throw("Para enviar el gerenciamiento es necesario el punto de comunicaciones disponibles.")
                                
    if not doc.riesgo_seguridad_física:
        frappe.throw("Para enviar el gerenciamiento es necesario el punto de riesgo seguridad física.")
        
    if not doc.autorizador:
        frappe.throw("Para enviar el gerenciamiento es necesario el autorizador.")
        
        
    if not doc.check_drogas:
        frappe.throw("Para enviar el gerenciamiento se debe de marcar el campo de 'Ud. (Conductor) se encuentra libre del efecto de cualquier medicamento, droga o alcohol'.")
        
    if not doc.check_sueno:
        frappe.throw("Para enviar el gerenciamiento se debe de marcar el campo de 'Ud. (Conductor) durmió por lo menos 6 horas continuas en las últimas 24 hrs'.")

    # VALIDAR DUPLICADOS
    empleados = []

    for fila in doc.acompañantes:

        if fila.nombre in empleados:
            frappe.throw(f"El empleado {fila.nombre} se encuentra repetido en la tabla de acompañantes.")

        empleados.append(fila.nombre)
        
if doc.workflow_state == "En transito":
    doc.fechahora_inicio_de_transito = frappe.utils.now()
    empleado = frappe.db.get_value("Employee", {"user_id": frappe.session.user}, "name")

    if empleado:
        doc.número_de_empleado_cecom = empleado

        # Obtener puesto y departamento del empleado
        datos_empleado = frappe.db.get_value(
            "Employee",
            empleado,
            ["designation", "department", "employee_name"],
            as_dict=True
        )

        if datos_empleado:
            doc.puesto_de_empleado_cecom = datos_empleado.designation
            doc.departamento_de_empleado_cecom = datos_empleado.department
            doc.nombre_de_empleado_cecom = datos_empleado.employee_name
            doc.usuario_cecom = frappe.session.user

if doc.workflow_state == "Finalizado":

    doc.fechahora_finalización_de_viaje = frappe.utils.now()


    if doc.fechahora_inicio_de_transito and doc.fechahora_finalización_de_viaje:
        inicio = frappe.utils.get_datetime(doc.fechahora_inicio_de_transito)
        fin = frappe.utils.get_datetime(doc.fechahora_finalización_de_viaje)
    
        if fin > inicio:
            segundos = (fin - inicio).total_seconds()
            
            horas = int(segundos // 3600)
            minutos = int((segundos % 3600) // 60)
            seg = int(segundos % 60)
            
            doc.tiempo_real = f"{horas}h {minutos}m {seg}s"

def cancelar_gerenciamiento_viajes(folio):

    frappe.db.set_value("Gerenciamiento de viajes", folio, {
        "workflow_state": "Cancelado",
        "docstatus": 2
    })

    frappe.db.commit()
    frappe.response["message"] = _(f"Estado actualizado a 'Cancelado' para {folio}.")

folio = frappe.form_dict.get('folio', ' ')
cancelar_gerenciamiento_viajes(folio)
